const fallbackNotices: Partial<Record<LegalLocale, string>> = {
  de: "",
  en: "",
  tr: "",
  pl: "",
  ar: "",
  fr: "",
  es: "",
  it: "",
};

export function getTermsDocument(language: string | null | undefined): LegalDocument {
  const locale = getLegalLocale(language);
  const directDocument = termsDocuments[locale];

  if (directDocument) {
    return directDocument;
  }

  const germanFallback = termsDocuments.de!;

  return {
    ...germanFallback,
    fallbackNotice: fallbackNotices[locale] ?? "",
  };
}